// states.js
const STORAGE_KEY = "state"

// Clear separation of what's persisted vs in-memory
const defaultPersisted = {
	filters:     {},
	submissions: [],
	data:        {},

	user:              null,
	isAuthenticated:   false,
	timeUp:            false,
	isInitialized:     false,
}

const defaultEphemeral = {
	navigationBlocked: false,
	currentRoute:      "/",
	queryParams:       null,
	componentLoading:  false,
}

let persistedState = loadFromStorage()
let ephemeralState = { ...defaultEphemeral }
const subscribers = []

function loadFromStorage() {
	try {
		const stored = sessionStorage.getItem(STORAGE_KEY)
		if (!stored) return { ...defaultPersisted }

		const loaded = JSON.parse(stored)
		// Merge with defaults to ensure new properties get added
		return { ...defaultPersisted, ...loaded }
	} catch (error) {
		console.error("State load failed, using defaults:", error)
		return { ...defaultPersisted }
	}
}

export function updateState(newState) {
	try {
		// Split updates using object structure
		const persistedUpdates = pick(newState, Object.keys(defaultPersisted))
		const ephemeralUpdates = pick(newState, Object.keys(defaultEphemeral))

		// Update ephemeral immediately
		Object.assign(ephemeralState, ephemeralUpdates)

		// Check persisted changes
		if (Object.keys(persistedUpdates).length > 0) {
			const newPersisted = { ...persistedState, ...persistedUpdates }
			if (JSON.stringify(persistedState) !== JSON.stringify(newPersisted)) {
				persistState(newPersisted)
				persistedState = newPersisted
			}
		}

		subscribers.forEach(cb => cb({ ...persistedState, ...ephemeralState }))
	} catch (error) {
		console.error("State update failed:", error)
		resetStates()
		subscribers.forEach(cb => cb({ ...persistedState, ...ephemeralState }))
	}
}

function persistState(state) {
	try {
		const serialized = JSON.stringify(state)
		if (serialized.length > 5_000_000) { // Rough 5MB check
			throw new Error("State too large")
		}
		sessionStorage.setItem(STORAGE_KEY, serialized)
	} catch (error) {
		console.warn("Storage failed, clearing:", error)
		sessionStorage.removeItem(STORAGE_KEY)
	}
}

function pick(obj, keys) {
	return Object.fromEntries(
		Object.entries(obj).filter(([k]) => keys.includes(k))
	)
}

function resetStates() {
	persistedState = { ...defaultPersisted }
	ephemeralState = { ...defaultEphemeral }
	sessionStorage.removeItem(STORAGE_KEY)
}

export function subscribe(callback) {
	subscribers.push(callback)
	return () => {
		const index = subscribers.indexOf(callback)
		if (index > -1) subscribers.splice(index, 1)
	}
}

export function getState() {
	return { ...persistedState, ...ephemeralState }
}
