function mapOptions(items) {
	return items.map(item => ({
		value: item.id.toString(),
		label: toTitleCase(item.name),
		bit:   item.bit
	}))
}

function getBitMaskValues(items, bitMask) {
	return items
		.filter(item => (item.bit & bitMask) !== 0)
		.map(item => item.id.toString())
}

class TableBuilder{
	constructor(tableBody) {
		this.tableBody = tableBody
		this.fields = new Map()
	}

	addField(field) {
		this.fields.set(field.key, field)
		return this
	}

	addDropdownMultiField(key, availableOptions, selectedBitMask) {
		const options = availableOptions.map(item => ({
			value: item.id.toString(),
			label: item.name,
			bit:   item.bit
		}))
		const selectedValues = getBitMaskValues(availableOptions, selectedBitMask)
		this.addField(new FieldDropdownMulti(key, options, selectedValues))
		return this
	}

	addExtraFields(extraJson) {
		const extraValues = extraJson ? JSON.parse(extraJson) : {}

		if (!extraValues || typeof extraValues !== "object") {
			return this
		}

		Object.entries(extraValues).forEach(([key, value]) => {
			// Check if field has predefined options
			if (extraValueMap[key]) {

				// FIXME: This is a hack to handle the "extra" fields
				// Must be refactored to use the same Field classes.
				// Try to add it into the existing fields from the initial setup to avoid duplication
				const options = extraValueMap[key].map((label, index) => ({
					id:   index.toString(),
					name: label,
					bit:  1 << index
				}))
				this.addDropdownMultiField( key, options, 1 << (value - 1)) // Convert value to bitmask

			} else {
				// Regular field without predefined options
				this.addField(new Field(key, value))
			}
		})

		return this
	}

	build() {
		if (!this.tableBody) return

		this.tableBody.innerHTML = Array.from(this.fields.entries())
			.map(([key, field]) => generateTableRow([
				translationKeyMap[key] || key,
				field
			]))
			.join("")

		this.fields.forEach(field => {
			if (typeof field.postRender === "function") {
				field.postRender()
			}
		})

		enableEditOnClick()
	}
}

export class FormBuilder{
	constructor(formElement) {
		this.form = formElement
		this.fields = new Map()
		this.setupFormHandler()
	}

	addField(field) {
		this.fields.set(field.key, field)
		return this
	}

	collectFormData() {
		const data = {}

		this.fields.forEach(field => {
			const key = field.key.toLowerCase()
			data[key] = field.getOutputValue()
		})

		// FIXME: This is a hack to handle the "extra" fields, was removed from the main data
		// Handle extra fields separately
		// const extraFields = Object.keys(extraValueMap).reduce((extra, key) => {
		// 	if (this.fields.has(key)) {
		// 		extra[key] = this.fields.get(key).getOutputValue()
		// 	}
		// 	return extra
		// }, {})

		// Remove extra fields from main data and add as JSON string
		// Object.keys(extraValueMap).forEach(key => {
		// 	delete data[key.toLowerCase()]
		// })
		// data.extra = extraFields

		return data
	}

	setupFormHandler() {
		if (!this.form) return

		this.form.onsubmit = async (e) => {
			e.preventDefault()
			const data = this.collectFormData()
			await this.submitUpdate(data)
		}
	}

	getBitMaskFromDropdown(field) {
		return Array.from(field.dropdown.querySelectorAll("input:checked"))
			.reduce((mask, input) => {
				const option = field.options?.find(opt => opt.value === input.value)
				return mask | (option ? option.bit : 0)
			}, 0)
	}

	getExtraFieldValue(field) {
		const selected = field.dropdown.querySelector("input:checked")
		return Array.from(field.dropdown.querySelectorAll("input"))
			.indexOf(selected) + 1
	}

	async submitUpdate(data) {
		try {
			const questionId = data.id
			delete data.id // don't send id in body

			const { response, error } = await fetchAPI("QUESTIONS.UPDATE", "PATCH", {id: questionId}, data)
			if (error || !response) {
				showModalX("error", "Error", error.message || "Error al cargar los resultados")
				return []
			}

			// Show success notification
			showModalX("success", "Actualizada", "Pregunta guardada correctamente")
		} catch (error) {
			showModalX("error", "Error", error.message || "Error al cargar los resultados")
		}
	}
}

export async function fetchMultipleResources(requests) {
	try {
		const results = await Promise.all(
			requests.map(async ([key, endpoint, id]) => {
				const data = id ? await apiRequestByID(endpoint, id) : await apiRequestRaw(endpoint)
				return [key, data[key]]
			})
		)
		return Object.fromEntries(results)
	} catch (error) {
		console.error("Failed to fetch resources:", error)
		throw error
	}
}

function enableEditOnClick() {
	// Handle both editable cells and answers
	document.querySelectorAll(".editable-cell, .editable-answer").forEach((element) => {
		const field = element.closest("tr").field

		element.addEventListener("click", () => {
			element.setAttribute("contenteditable", "true")
			element.focus()
		})

		element.addEventListener("keydown", (e) => {
			if (e.key === "Enter") {
				e.preventDefault()
				element.blur()
			}
		})

		element.addEventListener("blur", () => {
			element.setAttribute("contenteditable", "false")
			if (field) {
				field.updateValue(element.textContent.trim())
			}
		})
	})
}

function generateTableRow([key, field]) {
	const { class: cellClass, content: cellContent, attrs: cellAttrs } = field.renderTableCell()
	const baseClasses = "relative px-4 border-b border-zinc-950/5 dark:border-white/5 py-4 sm:first:pl-1 sm:last:pr-1"
	const keyTranslation = toTitleCase(translationKeyMap[key]) || toTitleCase(key)

	return `
    <tr class="has-[[data-row-link][data-focus]]:outline has-[[data-row-link][data-focus]]:outline-2 has-[[data-row-link][data-focus]]:-outline-offset-2 has-[[data-row-link][data-focus]]:outline-blue-500 dark:focus-within:bg-white/[2.5%] hover:bg-zinc-950/[2.5%] dark:hover:bg-white/[2.5%]">
        <td class="text-zinc-500 ${baseClasses}">
            <a data-row-link="true" tabindex="-1" class="absolute inset-0"></a>
            ${keyTranslation}
        </td>
        <td class="${cellClass}" ${cellAttrs}>
            ${cellContent}
        </td>
    </tr>
    `
}

export function populateQuestionTable(questionData, regions, institutions, categories, lessons) {
	const tableBody = document.querySelector("table tbody")
	const formElement = document.querySelector("#questionForm")

	// FIXME: As some questions retrieved from the database could have an index higher than its
	// possible questions, this avoids a TypeError
	questionData.accepted = questionData.accepted > questionData.answers.length - 1 ? 0 : questionData.accepted

	const selectedPart = !questionData.lesson_id ? 0 : (lessons.find(l => l.id === questionData.lesson_id)?.type === 0 ? 1 : 2) || 0
	const selectedLessonId = questionData.lesson_id

	// Map all lessons once for reuse
	const allLessons = lessons
		.filter(lesson => lesson.id !== 1) // Discard "undefined" lesson
		.sort((a, b) => { // Sort alphabetically by name (and numbers)
			// First sort by type (General/Specific)
			if (a.type !== b.type) return a.type - b.type

			// Extract all numbers from strings
			const numbersA = a.name.match(/\d+/g)?.map(Number) || []
			const numbersB = b.name.match(/\d+/g)?.map(Number) || []

			// Compare numbers in sequence
			for (let i = 0; i < Math.min(numbersA.length, numbersB.length); i++) {
				if (numbersA[i] !== numbersB[i]) {
					return numbersA[i] - numbersB[i]
				}
			}
			// If all numbers match, use string comparison
			return a.name.localeCompare(b.name)
		})
		.map(lesson => ({
			value: lesson.id.toString(),
			label: lesson.name,
			type:  lesson.type
		}))

	const partsDropdown = new FieldDropdown("lessonType", [
		{ value: "0", label: "Seleccionar..." },
		...extraValueMap.parts.map((label, index) => ({
			value: (index + 1).toString(),
			label: label
		}))
	], // this is the onChange part...
	selectedPart, (selectedValue) => {
		const partType = parseInt(selectedValue) - 1
		const filtered = [
			{ value: "0", label: "Seleccionar..." },
			...allLessons.filter(l => l.type === partType)
		]
		lessonDropdown.updateOptions(filtered)
		// lessonDropdown.setValue("0")
	})

	// Initialize lesson dropdown with correct options based on initial part
	const initialLessonOptions = [
		{ value: "0", label: "Seleccionar..." },
		...allLessons.filter(l => l.type === selectedPart - 1)
	]

	// const selectedLessonIndex = initialLessonOptions.findIndex(opt => opt.value === selectedLessonId.toString())
	// const lessonDropdown = new FieldDropdown("lesson_id", initialLessonOptions,
	// 	// Use the found index, or 0 if not found
	// 	selectedLessonIndex >= 0 ? selectedLessonIndex : 0
	// )

	// const lessonDropdown = new FieldDropdown("lesson_id", initialLessonOptions,
	// 	initialLessonOptions.some(opt => opt.value === selectedLessonId.toString())
	// 		? selectedLessonId
	// 		: "0" // Fallback to 0 if initial lesson not in filtered options
	// )

	const selectedLessonIndex = initialLessonOptions.findIndex(opt => opt.value === selectedLessonId.toString())
	const lessonDropdown = new FieldDropdown(
		"lesson_id",
		initialLessonOptions,
		selectedLessonIndex >= 0
			? selectedLessonIndex
			: "0" // Fallback to 0 if initial lesson not in filtered options
	)

	const fields = [
		new FieldNumber("id", questionData.id, FieldTypes.STATIC),
		new Field("question", questionData.question),
		new FieldDropdown("accepted", questionData.answers.map((answer, index) => ({
			value: index.toString(),
			label: ["A", "B", "C", "D"][index],
		})), questionData.accepted),
		new FieldAnswers("answers", questionData.answers),
		new Field("explanation", questionData.explanation),
		new FieldNumber("year", questionData.year || ""),
		new FieldDropdownMulti("categories", mapOptions(categories), questionData.categories),
		new FieldDropdownMulti("regions", mapOptions(regions), questionData.regions),
		new FieldDropdownMulti("institutions", mapOptions(institutions), questionData.institutions),
		new FieldDropdown("official", extraValueMap.official.map((label, index) => ({
			value: index.toString(),
			label: label,
			bit:   1 << index
		})), questionData.official || 0),

		partsDropdown,
		lessonDropdown
	]

	const table = new TableBuilder(tableBody)
	const form = new FormBuilder(formElement)

	fields.forEach(field => {
		table.addField(field)
		form.addField(field)
	})

	table.build()
}

export async function initializeQuestion(params) {
	const questionId = params.id
	if (!questionId) return

	try {
		const { questions, regions, institutions, categories, lessons} = await fetchMultipleResources([
			["questions", API.endpoints.QUESTIONS.BASE, questionId],
			["regions", API.endpoints.REGIONS.BASE],
			["institutions", API.endpoints.INSTITUTIONS.BASE],
			["categories", API.endpoints.CATEGORIES.BASE],
			["lessons", API.endpoints.LESSONS.BASE],
		])

		populateQuestionTable(questions[0], regions, institutions, categories, lessons)

		document.querySelector("#questionId").textContent = `#${questionId}`
		// questionStatus
		// document.querySelector("#questionStatus").textContent = questions[0].status === 1 ? "Activa" : "Archivada"

		const link = document.querySelector("#backLink")
		link.onclick = (e) => {
			e.preventDefault()
			loadComponent(link.getAttribute("href"))
		}
	} catch (error) {
		console.error("Failed to load question:", error)
	}
}
