import * as echarts from "echarts"

export class Charts{
	resizeCharts() {
		const lineChart = echarts.getInstanceByDom(document.getElementById("chart-container"))
		const gaugeChart = echarts.getInstanceByDom(document.getElementById("gauge-chart-container"))
		if (lineChart) lineChart.resize()
		if (gaugeChart) gaugeChart.resize()
	}

	initializeLineChart(containerId, xAxis, yAxis, chartData, isDark = false, isStacked = false) {
		var theme = isDark ? "dark" : ""
		const date = new Date()
		const formattedDate = new Intl.DateTimeFormat("en-CA", { // en-CA defaults to "yyyy-MM-dd"
			timeZone: "Europe/Madrid"
		}).format(date)


		var dom = document.getElementById(containerId)
		if (!dom) {
			console.error(`Element with id '${containerId}' not found.`)
			return
		}

		var myChart = echarts.init(dom, theme, {
			renderer:     "canvas",
			useDirtyRect: false
		})

		const legendItemWidth = 120 // tweak if labels are shorter/longer
		const itemsPerRow = Math.max(1, Math.floor(window.innerWidth / legendItemWidth))
		const legendRows = Math.ceil(xAxis.length / itemsPerRow)
		const bottomPadding = 20 + legendRows * 18 // base gap + 18px per legend row

		const option = {
			title: {
				// text: isStacked ? "Stacked Area Chart" : "Line Chart",
				// left: "center"
			},
			tooltip: {
				trigger:     "axis",
				axisPointer: {
					type:  "cross",
					label: {
						backgroundColor: "#6a7985"
					}
				}
			},
			legend: {
				data:      xAxis,
				bottom:    0,
				textStyle: {
					color: "#999"
				},
				// Unselect emtpy series by default
				selected: xAxis.reduce((acc, name, index) => {
					acc[name] = chartData[index].some(value => value !== 0)
					return acc
				}, {})
			},
			toolbox: {
				feature: {
					saveAsImage: {
						name:      `gráfica-temas-saludeduca-${formattedDate}`,
					},
					magicType:   {show: true, type: ["line", "bar", "stack", "tiled"]},
				}
			},
			grid: {
				left:         "3%",
				right:        "4%",
				bottom:       bottomPadding, // `${window.innerWidth > 1024 ? 25 : window.innerWidth > 640 ? 20 : 35}%`,
				containLabel: true
			},
			xAxis: {
				type:        "category",
				boundaryGap: !isStacked, // Non-stacked: true, Stacked: false
				data:        yAxis
			},
			yAxis: {
				type: "value"
			},
			series: chartData.map((arrayValue, index) => ({
				name:      xAxis[index],
				type:      "line",
				stack:     isStacked ? "Total" : undefined,
				areaStyle: isStacked ? {} : undefined,
				emphasis:  {
					focus: "series"
				},
				data:     arrayValue,
			}))
		}

		myChart.setOption(option)
		// window.addEventListener("resize", myChart.resize)
		window.addEventListener("resize", () => {
			myChart.setOption({
				grid: {
					...option.grid,
					// bottom: `${window.innerWidth > 1024 ? 25 : window.innerWidth > 640 ? 20 : 35}%`
					bottom: 20 + legendRows * 18
				}
			})
			myChart.resize()
		})
	}

	initializeGaugeChart(containerId, value, isDark = false) {
		var theme = isDark ? "dark" : ""
		const date = new Date()
		const formattedDate = new Intl.DateTimeFormat("en-CA", { // en-CA defaults to "yyyy-MM-dd"
			timeZone: "Europe/Madrid"
		}).format(date)

		var dom = document.getElementById(containerId)
		if (!dom) {
			console.error(`Element with id '${containerId}' not found.`)
			return
		}

		var myChart = echarts.init(dom, theme, {
			renderer:     "canvas",
			useDirtyRect: false
		})

		// Function to get motivational messages
		function getMotivationalMessage(score) {
			if (score < 25) return "¡Sigue adelante, cada paso cuenta! 🚀"
			if (score < 50) return "¡Vas por buen camino, sigue así! 🔥"
			if (score < 75) return "¡Gran esfuerzo, estás cerca de la excelencia! 💪"
			return "¡Lo lograste, excelente trabajo! 🏆"
		}

		function getScoreMessage(score) {
			if (score < 25) return "Principiante"
			if (score < 50) return "Nivel intermedio"
			if (score < 75) return "Nivel avanzado"
			return "Nivel experto"
		}

		const option = {
			tooltip: {
				show:      true,
				formatter: function (params) {
					const score = Math.round(params.value)
					return `Puntación: ${score}% <br/>${getMotivationalMessage(score)}`
				}
			},
			toolbox: {
				feature: {
					saveAsImage: {
						name: `gráfica-termómetro-saludeduca-${formattedDate}`,
					}
				}
			},
			series: [
				{
					type:     "gauge",
					progress: {
						show:  false,
						width: 18
					},
					axisLine: {
						lineStyle: {
							width: 18,
							color: [
								[0.25, "#f59695"],
								[0.5, "#fcd98e"],
								[0.75, "#cbda9e"],
								[1, "#b4dca0"]
							]
						}
					},
					axisTick: {
						show: false
					},
					splitLine: {
						length:    15,
						lineStyle: {
							width: 2,
							color: "#999"
						}
					},
					axisLabel: {
						distance: 25,
						color:    "#999"
					},
					pointer: {
						itemStyle: {
							color:       "#999",
							borderColor: "#666"
						}
					},
					title: {
						show: false
					},
					detail: {
						valueAnimation: true,
						offsetCenter:   [0, "70%"],
						formatter:      function (val) {
							return getScoreMessage(val)
						},
						fontSize: 16,
						color:       "#999",
					},
					data: [
						{ value: value * 100 }
					],
				}
			]
		}

		myChart.setOption(option)
		window.addEventListener("resize", myChart.resize)
	}
}
