import {
	GAME_CONFIG_PARTS,
	SUCCESS_THRESHOLD_SIMULATION,
	SUCCESS_THRESHOLD_STUDY,
	getGamePartKeyFromType
} from "../environment.js"

export const StatsCalculations = {
	calculateSuccessRatio(userStats) {
		if (!Array.isArray(userStats) || userStats.length === 0) {
			return 0
		}

		// Calculate totals directly from all stats
		const totals = userStats.reduce((acc, stat) => {
			acc.passed += stat.questions_passed
			acc.failed += stat.questions_failed
			acc.listed += stat.questions_listed
			return acc
		}, { passed: 0, failed: 0, listed: 0 })

		// Calculate success ratio
		const totalAnswered = totals.passed + totals.failed
		if (totalAnswered === 0) {
			return 0
		}

		return parseFloat((totals.passed / totalAnswered * 100).toFixed(2))
	},

	calculateStreak(userStats) {
		if (!Array.isArray(userStats) || userStats.length === 0) {
			return 0
		}
		const today = new Date()

		// Sort stats by date in descending order (most recent first)
		const sortedStats = userStats.sort((a, b) =>
			new Date(b.stat_date) - new Date(a.stat_date)
		)

		// remove today's stats if empty
		const todayStats = sortedStats[0]
		const todayDate = new Date(todayStats.stat_date)
		if (todayStats && todayStats.questions_passed + todayStats.questions_failed + todayStats.questions_listed === 0) {
			const isToday = today.toDateString() === todayDate.toDateString()
			if (isToday) sortedStats.shift()
		}

		// Check if most recent activity was today or yesterday
		today.setHours(0, 0, 0, 0)
		const mostRecentDate = new Date(sortedStats[0].stat_date)
		const daysSinceLastActivity = Math.floor((today - mostRecentDate) / (1000 * 60 * 60 * 24))

		if (daysSinceLastActivity > 1) {
			return 0 // Break streak if no activity in last two days
		}

		// Count consecutive days
		let streak = 0
		let previousDate = null

		for (const stat of sortedStats) {
			const currentDate = new Date(stat.stat_date)
			const hasActivity = stat.questions_passed + stat.questions_failed + stat.questions_listed > 0

			if (!hasActivity) {
				break
			}

			if (previousDate) {
				const dayDifference = Math.floor((previousDate - currentDate) / (1000 * 60 * 60 * 24))
				if (dayDifference !== 1) {
					break // Break streak if days aren't consecutive
				}
			}

			streak++
			previousDate = currentDate
		}

		return streak
	},

	calculateSubmissionScore(submission) {
		const part = submission.submissionMode // FIXME: Replace by a real database value, such as submission.submissionMode
		const config = GAME_CONFIG_PARTS[getGamePartKeyFromType(part)]

		const relevantQuestions = submission.questionsAnswers.slice(0, config.validQuestions)
		const correct = relevantQuestions.filter(a => a.selectedAnswer === a.accepted).length
		const incorrect = relevantQuestions.filter(a => a.selectedAnswer !== a.accepted && a.selectedAnswer !== null).length

		// Calculate final score with more precision
		const finalScore = Number((correct * config.pointsPerCorrect - incorrect * config.pointsPerIncorrect).toFixed(3))
		// No rounding needed here since we already have precise calculation
		const normalizeScore = Math.max(0, Math.min(10, finalScore)).toFixed(3)

		// if it's a round number remove the decimal part
		if (normalizeScore % 1 === 0) {
			return Math.round(normalizeScore)
		}
		return normalizeScore
	},

	isApproved(submission) {
		if (submission.submissionType === "simulation") {
			const score = this.calculateSubmissionScore(submission)
			return score >= this.calculateLowestPassingScore(submission)

		} else if (submission.submissionType === "study") {
			const successRate = submission.answersPassed / submission.questionsAnswers.length
			return successRate >= SUCCESS_THRESHOLD_STUDY
		}
		else {
			console.error("Unknown submission type:", submission.submissionType)
			return false
		}
	},

	/**
	 * Calculates success rate for a specific number of days
	 * @param {Array} stats - Array of daily statistics
	 * @param {number} daysBack - Number of days to calculate
	 * @returns {number} Success rate percentage or 0 if no data
	 */
	calculateSuccessRateForDays(stats, daysBack) {
		if (!Array.isArray(stats) || stats.length === 0) {
			return 0
		}

		// Sort by date descending and get last n days
		const relevantStats = stats
			.sort((a, b) => new Date(b.stat_date) - new Date(a.stat_date))
			.slice(0, daysBack)

		// Calculate totals for the period
		const totals = relevantStats.reduce((acc, stat) => {
			acc.passed += stat.questions_passed
			acc.failed += stat.questions_failed
			return acc
		}, { passed: 0, failed: 0 })

		const totalAnswered = totals.passed + totals.failed
		if (totalAnswered === 0) {
			return 0
		}

		return parseFloat((totals.passed / totalAnswered * 100).toFixed(2))
	},

	/**
	 * Calculates the gauge score based on multiple factors
	 * @param {Array} userStats - Daily user statistics
	 * @param {Array} submissions - User submissions history
	 * @param {number} totalQuestions - Total available questions
	 * @returns {number} Score between 0 and 1
	 */
	calculateGaugeScore(userStats, submissions, totalQuestions) {
		const answersScore = Math.min(1, this.calculateAnswersScore(userStats, totalQuestions))
		const simulationsScore = Math.min(1, this.calculateSimulationsScore(submissions))
		const streakScore = Math.min(1, this.calculateNonStrictStreakScore(userStats))

		// Weight each component
		return (answersScore * 0.7) + (simulationsScore * 0.2) + (streakScore * 0.1)
	},

	/**
	 * Calculates the score based on correctly answered questions (70%)
	 * @param {Array} userStats - Daily user statistics for last 30 days
	 * @param {number} totalQuestions - Total available questions
	 * @returns {number} Score between 0 and 1
	 */
	calculateAnswersScore(userStats, totalQuestions) {
		if (!Array.isArray(userStats) || userStats.length === 0 || !totalQuestions) {
			return 0
		}

		// Get last 30 days stats
		const last30DaysStats = userStats
			.sort((a, b) => new Date(b.stat_date) - new Date(a.stat_date))
			.slice(0, 30)

		// Sum passed questions
		const totalPassed = last30DaysStats.reduce((sum, stat) =>
			sum + (stat.questions_passed || 0), 0)

		return Math.min(totalPassed / totalQuestions, 1)
	},

	/**
	 * Calculates score based on last 5 simulations (20%)
	 * @param {Array} submissions - User submissions
	 * @returns {number} Score between 0 and 1
	 */
	calculateSimulationsScore(submissions) {
		if (!Array.isArray(submissions) || submissions.length === 0) {
			return 0
		}

		// Get last 5 simulations
		const lastSimulations = submissions
			.filter(s => s.submissionType === "simulation")
			.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
			.slice(0, 5)

		if (lastSimulations.length === 0) {
			return 0
		}

		// Calculate average score
		const scores = lastSimulations.map(simulation => {
			const status = this.calculateSubmissionScore(simulation) / 10
			return typeof status === "string"
				? parseFloat(status)
				: status
		})

		const averageScore = scores.reduce((sum, score) => sum + score, 0) / 5 // lastSimulations.length
		return averageScore
	},

	/**
	 * Calculates non-strict streak score (10%)
	 * @param {Array} userStats - Daily user statistics
	 * @returns {number} Score between 0 and 1
	 */
	calculateNonStrictStreakScore(userStats) {
		if (!Array.isArray(userStats) || userStats.length === 0) {
			return 0
		}

		// Get last 10 days stats
		const last10DaysStats = userStats
			.sort((a, b) => new Date(b.stat_date) - new Date(a.stat_date))
			.slice(0, 10)

		// Count days with activity (non-strict streak)
		const daysWithActivity = last10DaysStats.filter(stat =>
			(stat.questions_passed || 0) + (stat.questions_failed || 0) > 0
		).length

		// Cap at 5 days (2% each day = 10% max)
		return Math.min(daysWithActivity, 5) / 5
	},

	calculateLowestPassingScore(submission) {
		if (submission.submissionType === "simulation") {
			return SUCCESS_THRESHOLD_SIMULATION * 10
		}
		return SUCCESS_THRESHOLD_STUDY * 10
	},

	/**
	 * Determines the best interval for calculating improvement
	 * @param {Array} stats - Array of daily statistics
	 * @returns {Object} Best interval info
	 */
	determineBestInterval(stats) {
		if (!Array.isArray(stats) || stats.length === 0) {
			return { days: 0, hasData: false }
		}

		// Sort stats by date descending
		const sortedStats = stats.sort((a, b) =>
			new Date(b.stat_date) - new Date(a.stat_date)
		)

		// Define intervals to check
		const intervals = [7, 10, 15, 20, 30]

		// Find first interval with data
		for (const days of intervals) {
			const relevantStats = sortedStats.slice(0, days)
			const hasActivity = relevantStats.some(stat =>
				stat.questions_passed + stat.questions_failed > 0
			)

			const todayRate = this.calculateSuccessRateForDays(relevantStats, 1)
			const periodRate = this.calculateSuccessRateForDays(relevantStats, days)

			return {
				days,
				hasData:    hasActivity,
				todayRate:  todayRate,
				periodRate: periodRate
			}

		}

		return { days: 0, hasData: false }
	},

	/**
	 * Calculates the number of passed submissions
	 * @param {Array} submissions - Array of submission history
	 * @returns {Object} Count of passed simulations and studies
	 */
	calculatePassedSubmissions(submissions) {
		return submissions.reduce((acc, submission) => {
			if (!submission.questionsAnswers?.length) {
				return acc
			}

			if (submission.submissionType === "simulation") {
				const score = this.calculateSubmissionScore(submission)
				const isApproved = score >= this.calculateLowestPassingScore(submission)
				if (isApproved) acc.simulations++

			} else if (submission.submissionType === "study") {
				const successRate = submission.answersPassed / submission.questionsAnswers.length
				const isApproved = successRate >= SUCCESS_THRESHOLD_STUDY
				if (isApproved) acc.studies++
			}

			return acc
		}, { simulations: 0, studies: 0 }) // Initialize with zero counts
	},

	determineImprovement(interval) {
		if (!interval.hasData) return null
		if (interval.periodRate === 0) return interval.todayRate > 0 ? 100 : 0 // Would be interesting to show a negative improvement to just show that the period rate is being calculated.
		if (interval.todayRate === 0) return interval.periodRate // Return 0 when today's rate is 0

		// Calculate improvement percentage
		const improvementPercent = ((interval.todayRate - interval.periodRate) / Math.abs(interval.periodRate) * 100)
		return Math.min(improvementPercent, 1000) // Cap at 1000% and return numeric value
	}
}
