// filters.js

import { API } from "../api.js"
import { Component } from "../components.js"
import { loadComponent } from "../router.js"
import { updateState } from "../states.js"
import { translations, userLanguage } from "../translations.js"
import { apiRequest } from "../utils.js"
import { showModalX } from "../modals.js"
import {
	createNavLink,
	generateButton,
	generateDropdown,
	generateQuantityField,
	generateSearchBox,
	generateSwitch,
	generateTable
} from "./components.js"

import {
	STUDY_DEFAULT_VALUE,
	STUDY_MAX_QUESTIONS,
	STUDY_MIN_QUESTIONS,
	GAME_CONFIG_PARTS,
	GAME_PARTS_DEFAULT,
} from "../environment.js"

const filterConfigs = {
	study: {
		targetRoute: "/study/play",
		fields:      [
			...(Object.keys(GAME_CONFIG_PARTS).length > 1 ? [{
				type:    "dropdown",
				name:    "partType",
				label:   "Tipo de estudio",
				options: Object.values(GAME_CONFIG_PARTS)
					.sort((a, b) => b.partType === GAME_CONFIG_PARTS[GAME_PARTS_DEFAULT].partType ? 1 : -1)
					.map(p => ({
						value: p.partType,
						label: p.label
					}))
			}] : []),
			{
				type:           "table", name:           "table", label:          "", headerPosition: "firstColumn", alignment:      "left",
				rows:           [["Número de preguntas", "Personalizado"], ["Tiempo", "Indefinido"]]
			},
			{ type: "quantity", name: "amount", label: "Número de preguntas", value: STUDY_DEFAULT_VALUE, min: STUDY_MIN_QUESTIONS, max: STUDY_MAX_QUESTIONS },
			{ type: "search", name: "topics", label: "Temas", options: (instance) => instance.getTopics() },
			// { type: "switch", name: "failed", label: "Incluir preguntas falladas anteriormente" },
			{ type: "button", name: "submit", label: "Iniciar Estudio", buttonType: "submit" },
		]
	},
	simulation: {
		targetRoute: "/simulation/play",
		fields:      [
			...(Object.keys(GAME_CONFIG_PARTS).length > 1 ? [{
				type:    "dropdown",
				name:    "partType",
				label:   "Tipo de estudio",
				options: Object.values(GAME_CONFIG_PARTS)
					.sort((a, b) => b.partType === GAME_CONFIG_PARTS[GAME_PARTS_DEFAULT].partType ? 1 : -1)
					.map(p => ({
						value: p.partType,
						label: p.label
					}))
			}] : []),
			{
				type:           "table", name:           "table", label:          "", headerPosition: "firstColumn", alignment:      "left",
				rows:           [
					["Número de preguntas", `${GAME_CONFIG_PARTS[GAME_PARTS_DEFAULT].defaultQuestions}`],
					["Tiempo", `${GAME_CONFIG_PARTS[GAME_PARTS_DEFAULT].defaultTime} minutos`]
				]
			},
			{ type: "search", name: "topics", label: "Temas", options: (instance) => instance.getTopics() },
			{ type: "button", name: "submit", label: "Iniciar Simulación", buttonType: "submit" },
		]
	}
}

/**
 * Gets the part key from the simulation type
 * @param {string} partType - The type of simulation ('general' or 'specific')
 * @returns {string} The key of the part configuration or GAME_PARTS_DEFAULT
 */
function getPartKeyFromType(partType) {
	return Object.entries(GAME_CONFIG_PARTS)
		.find(([_, part]) => part.partType === partType)?.[0]
        || GAME_PARTS_DEFAULT
}

/**
 * Filters component for handling study and simulation filter forms
 * @class
 * @extends Component
 */
class Filters extends Component{
	/**
	 * Creates a new Filters instance
	 * @param {string} type - The type of filter ('study' or 'simulation')
	 */
	constructor(type) {
		super("filters")
		this.type = type
		this.partsData = Object.keys(GAME_CONFIG_PARTS).reduce((acc, key) => {
			acc[key] = { ...GAME_CONFIG_PARTS[key], topics: [] }
			return acc
		}, {})
	}

	/**
	 * Gets available topics for all parts
	 * @returns {Object.<string, Object>} Map of part types to their topic options
	 */
	getTopics() {
		return Object.entries(GAME_CONFIG_PARTS).reduce((acc, [key, part]) => {
			acc[part.partType] = this.generateTopicOptions(key)
			return acc
		}, {})
	}

	/**
	 * Fetches additional values from the API
	 * @returns {Promise<Object>} The API response containing parts data
	 */
	async fetchExtraValues() {
		try {
			const { response, error } = await apiRequest(API.endpoints.QUESTIONS.EXTRAS)
			if (error) throw error

			if (!response?.success || response.data.parts === null || typeof response.data.parts !== "object") {
				console.error("Invalid API response structure")
				return { data: [] }
			}

			return response.data

		} catch (err) {
			console.error("Fetch Questions Failed:", err)
			return { data: [] }
		}
	}

	async fetchAvailableLessons() {
		try {
			const { response, error } = await apiRequest(API.endpoints.LESSONS.SELF)
			if (error) throw error

			if (!response?.success || response.data.types === null || typeof response.data.types !== "object") {
				console.error("Invalid API response structure")
				return { data: [] }
			}

			return response.data

		} catch (err) {
			console.error("Fetch Questions Failed:", err)
			return { data: [] }
		}
	}

	generateTopicOptions(partKey) {
		return this.partsData[partKey].topics.reduce((acc, lesson) => {
			acc[lesson.id] = lesson.name
			return acc
		}, {})
	}

	/**
	 * Generates topic options for a specific part
	 * @param {string} partKey - The key of the part configuration
	 * @returns {Object.<string, string>} Map of topic keys to their labels
	 */
	generateTopicOptionsV0(partKey) {
		const options = this.partsData[partKey].topics.reduce((acc, lesson) => {
			const key = `extra_parts:${partKey}_lesson:${lesson}`
			const label = `${translations[userLanguage].lesson} ${lesson} ${GAME_CONFIG_PARTS[partKey].label}`
			acc[key] = label
			return acc
		}, {})

		return options
	}

	/**
	 * Gets the current part configuration based on simulation type
	 * @param {string} partType - The type of simulation
	 * @returns {Object} The part configuration
	 */
	getCurrentPart(partType) {
		const partKey = getPartKeyFromType(partType)
		return this.partsData[partKey] || this.partsData[1]
	}

	/**
	 * Initializes the filter component and renders the form
	 * @returns {Promise<void>}
	 */
	async initialize() {
		try {
			const { parts } = await this.fetchExtraValues()
			const { types } = await this.fetchAvailableLessons()

			// Update parts data with dynamic topics
			Object.keys(GAME_CONFIG_PARTS).forEach(partKey => {
				this.partsData[partKey] = {
					...GAME_CONFIG_PARTS[partKey],
					topics:       types[partKey] || [], // Use empty array if no parts
				}
				// this.partsData[partKey].topicOptions = this.generateTopicOptions(partKey)
			})

		} catch (error) {
			console.error("Failed to load parts data:", error)
			this.partsData = structuredClone(GAME_CONFIG_PARTS)
		}

		const config = filterConfigs[this.type]
		if (!config) {
			console.error(`No configuration found for filter type: ${this.type}`)
			return
		}

		const mainContent = document.querySelector("#main-content")
		if (!mainContent) throw new Error("Main content element not found")

		const formSection = document.querySelector("#filters-content")
		if (!formSection) throw new Error("Filters form not found")
		formSection.innerHTML = "" // Clear previous content if necessary

		const backlink = createNavLink("/", "Inicio")
		// FIXME: Could this be made more generic?
		backlink.onclick = (e) => {
			e.preventDefault()
			const path = backlink.getAttribute("href")
			loadComponent(path)
		}
		formSection.appendChild(backlink)

		// Create form header
		const header = this.generateFormHeader(
			translations[userLanguage].filterHeaders[this.type].title,
			translations[userLanguage].filterHeaders[this.type].description
		)
		formSection.appendChild(header)

		const form = document.createElement("form")
		form.id = `${this.type}FiltersForm`
		form.className = "bg-white dark:bg-zinc-900 rounded-lg shadow p-6 space-y-6 max-w-md mx-auto"

		// Create form content based on configuration
		this.createFormContent(form, this.type, config.fields)
		formSection.appendChild(form)

		this.updateTableAndSearch(form, GAME_PARTS_DEFAULT)

		// Save target route to state for routing after submission
		this.targetRoute = config.targetRoute
	}

	/**
	 * Generates the form header with title and description
	 * @param {string} title - The header title
	 * @param {string} description - The header description
	 * @returns {HTMLElement} The header element
	 */
	generateFormHeader(title, description) {
		// Create the main header container
		const header = document.createElement("div")
		header.className = "flex flex-wrap items-center gap-6 justify-left p-6 space-y-6 max-w-md mx-auto"

		// Create the inner div container
		const innerContainer = document.createElement("div")

		// Create the title container with flex
		const titleContainer = document.createElement("div")
		titleContainer.className = "flex flex-wrap items-center gap-x-4 gap-y-2"

		// Create the title element
		const titleElement = document.createElement("h1")
		titleElement.className = "text-2xl/8 font-semibold text-zinc-950 sm:text-xl/8 dark:text-white"
		titleElement.textContent = title
		titleContainer.appendChild(titleElement)

		// Add the date and location container
		const dateLocation = document.createElement("div")
		dateLocation.className = "mt-2 text-sm/6 text-zinc-500"
		dateLocation.innerHTML = `${description}`

		// Append the title container and date location to the inner container
		innerContainer.appendChild(titleContainer)
		innerContainer.appendChild(dateLocation)

		// Append the inner container to the main header
		header.appendChild(innerContainer)

		return header
	}

	updateTable(form, currentPart) {
		const cells = form.querySelectorAll("dd")

		if (this.type === "study") {
			cells[0].textContent = "Personalizado"
			cells[1].textContent = "Indefinido"
		}
		else if (this.type === "simulation") {
			cells[0].textContent = currentPart.defaultQuestions
			cells[1].textContent = `${currentPart.defaultTime} minutos`
		}
	}

	updateSearchV0(form, currentPart, orderBy = "label") {
		// Update search with current part's topics
		const searchContainer = form.querySelector(".overflow-y-auto")
		searchContainer.innerHTML = ""

		const sortFunctions = {
			lesson: (a, b) => {
				// Extract lesson numbers from the keys using regex
				const aLesson = parseInt(a[0].match(/lesson:(\d+)/)[1])
				const bLesson = parseInt(b[0].match(/lesson:(\d+)/)[1])
				return aLesson - bLesson
			},
			label: (a, b) => {
				// Extract numbers from the labels for proper numerical sorting
				const aNum = parseInt(a[1].match(/\d+/)[0])
				const bNum = parseInt(b[1].match(/\d+/)[0])
				return aNum - bNum
			}
		}

		// Sort topics using the specified sorting function
		const sortedTopics = Object.entries(currentPart.topicOptions).sort(sortFunctions[orderBy])

		sortedTopics.forEach(([key, label]) => {
			const checkboxLabel = document.createElement("label")
			checkboxLabel.className = "flex items-center space-x-3 cursor-pointer mb-2"

			const checkbox = document.createElement("input")
			checkbox.type = "checkbox"
			checkbox.name = "topics"
			checkbox.value = key
			checkbox.className = "sr-only"

			const checkIndicator = document.createElement("span")
			checkIndicator.className = "flex h-5 w-5 items-center justify-center border-2 border-zinc-400 rounded-md dark:border-zinc-600 transition-colors"

			const checkMark = document.createElementNS("http://www.w3.org/2000/svg", "svg")
			checkMark.setAttribute("xmlns", "http://www.w3.org/2000/svg")
			checkMark.setAttribute("class", "h-3 w-3 text-white")
			checkMark.setAttribute("fill", "none")
			checkMark.setAttribute("viewBox", "0 0 24 24")
			checkMark.setAttribute("stroke", "currentColor")
			checkMark.setAttribute("stroke-width", "2")

			const path = document.createElementNS("http://www.w3.org/2000/svg", "path")
			path.setAttribute("stroke-linecap", "round")
			path.setAttribute("stroke-linejoin", "round")
			path.setAttribute("d", "M5 13l4 4L19 7")
			checkMark.appendChild(path)

			checkMark.style.display = "none"
			checkIndicator.appendChild(checkMark)

			checkbox.addEventListener("change", () => {
				if (checkbox.checked) {
					checkIndicator.classList.add("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
					checkMark.style.display = "block"
				} else {
					checkIndicator.classList.remove("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
					checkMark.style.display = "none"
				}
			})

			const optionLabel = document.createElement("span")
			optionLabel.className = "text-sm text-zinc-900 dark:text-zinc-100"
			optionLabel.textContent = label

			checkboxLabel.appendChild(checkbox)
			checkboxLabel.appendChild(checkIndicator)
			checkboxLabel.appendChild(optionLabel)
			searchContainer.appendChild(checkboxLabel)
		})
	}

	updateSearch(form, currentPart) {
		// Update search with current part's topics
		const searchContainer = form.querySelector(".overflow-y-auto")
		searchContainer.innerHTML = ""

		currentPart.topics.forEach(topic => {
			const checkboxLabel = document.createElement("label")
			checkboxLabel.className = "flex items-center space-x-3 cursor-pointer mb-2"

			const checkbox = document.createElement("input")
			checkbox.type = "checkbox"
			checkbox.name = "topics"
			checkbox.value = topic.id
			checkbox.className = "sr-only"

			const checkIndicator = document.createElement("span")
			checkIndicator.className = "flex h-5 w-5 items-center justify-center border-2 border-zinc-400 rounded-md dark:border-zinc-600 transition-colors"

			const checkMark = document.createElementNS("http://www.w3.org/2000/svg", "svg")
			checkMark.setAttribute("xmlns", "http://www.w3.org/2000/svg")
			checkMark.setAttribute("class", "h-3 w-3 text-white")
			checkMark.setAttribute("fill", "none")
			checkMark.setAttribute("viewBox", "0 0 24 24")
			checkMark.setAttribute("stroke", "currentColor")
			checkMark.setAttribute("stroke-width", "2")

			const path = document.createElementNS("http://www.w3.org/2000/svg", "path")
			path.setAttribute("stroke-linecap", "round")
			path.setAttribute("stroke-linejoin", "round")
			path.setAttribute("d", "M5 13l4 4L19 7")
			checkMark.appendChild(path)

			checkMark.style.display = "none"
			checkIndicator.appendChild(checkMark)

			checkbox.addEventListener("change", () => {
				if (checkbox.checked) {
					checkIndicator.classList.add("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
					checkMark.style.display = "block"
				} else {
					checkIndicator.classList.remove("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
					checkMark.style.display = "none"
				}
			})

			const optionLabel = document.createElement("span")
			optionLabel.className = "text-sm text-zinc-900 dark:text-zinc-100"
			optionLabel.textContent = `${topic.name}` // Lesson checkbox label text

			checkboxLabel.appendChild(checkbox)
			checkboxLabel.appendChild(checkIndicator)
			checkboxLabel.appendChild(optionLabel)
			searchContainer.appendChild(checkboxLabel)
		})
	}

	/**
	 * Updates the table and search components based on selected part
	 * @param {HTMLFormElement} form - The form element
	 * @param {string} value - The selected part value
	 */
	updateTableAndSearch(form, value) {
		const partKey = getPartKeyFromType(value)
		const currentPart = this.partsData[partKey]

		this.updateTable(form, currentPart)
		this.updateSearch(form, currentPart)
	}

	/**
	 * Creates form content based on field configurations
	 * @param {HTMLFormElement} form - The form element
	 * @param {string} type - The type of filter
	 * @param {Array<Object>} fields - The field configurations
	 * @returns {HTMLFormElement} The populated form
	 */
	createFormContent(form, filterType, fields) {
		let fieldElement

		fields.forEach((field) => {
			switch (field.type) {
			case "button":
				fieldElement = document.createElement("div")
				fieldElement.className = "flex justify-end mt-6"
				fieldElement.appendChild(
					generateButton(field.name, field.label, field.buttonType, "primary", field.classList)
				)
				break
			case "quantity":
				fieldElement = generateQuantityField(field.name, "", field.value, field.min, field.max)
				break
			case "switch":
				fieldElement = generateSwitch(field.name, field.label)
				break
			case "search":
				fieldElement = generateSearchBox("Buscar temas...", field.options, "w-full", "h-64", field.name)
				break
			case "dropdown":
				fieldElement = generateDropdown(field.name, field.label, field.options, null, (value) => {
					this.updateTableAndSearch(form, value)
				})
				break
			case "table":
				fieldElement = generateTable(field.headerPosition, field.alignment, field.rows)
				break
			default:
			// error
				console.error("Invalid field type:", field.type)
			}
			form.appendChild(fieldElement)
		})

		// Attach event listener for form submission after adding to the DOM
		form.addEventListener("submit", (event) => this.handleFormSubmit(event, filterType))
		return form
	}

	/**
	 * Handles form submission
	 * @param {Event} event - The form submission event
	 * @param {string} type - The type of filter
	 */
	handleFormSubmitV0(event, type) {
		event.preventDefault()
		const formData = new FormData(event.target)
		const params = {}
		const partType = formData.get("partType")
		const partKey = getPartKeyFromType(partType)
		const currentPart = this.partsData[partKey]

		// Set defaults from config
		params.amount = formData.get("amount") || currentPart.defaultQuestions
		params.topics = formData.getAll("topics") ||
			currentPart.topics.map(lesson => `extra_parts:${partKey}_lesson:${lesson}`)

		// Update state with form data
		updateState({ filters: params })

		// Navigate to the appropriate page based on the form type
		loadComponent(`/${type}/play`)
	}

	handleFormSubmit(event, type) {
		event.preventDefault()
		const formData = new FormData(event.target)
		const params = {}
		const partType = formData.get("partType")
		const partKey = getPartKeyFromType(partType)
		const currentPart = this.partsData[partKey]

		const selectedTopics = formData.getAll("topics") ||
			 currentPart.topics.map(lesson => lesson.id.toString())
		if (!selectedTopics || selectedTopics.length === 0) {
			showModalX("error", "ERROR DE VALIDACIÓN", "Debes seleccionar al menos un tema")
			return
		}

		// Set defaults from config
		params.amount = formData.get("amount") || currentPart.defaultQuestions
		params.submissionMode = partType || GAME_CONFIG_PARTS[GAME_PARTS_DEFAULT].partType
		params.topics = selectedTopics

		// Update state with form data
		updateState({ filters: params })

		// Navigate to the appropriate page
		loadComponent(`/${type}/play`)
	}
}

/**
 * Initializes the filters component
 * @param {string} type - The type of filter ('study' or 'simulation')
 */
export const initializeFilters = (type) => {
	const filtersComponent = new Filters(type)
	filtersComponent.initialize()
}
