// | Unit    | Conversion Formula    | Value   |
// | ------- | --------------------- | ------- |
// | Seconds | 60         (1 minute) | 60      |
// | Minutes | 60×60      (1 hour)   | 3,600   |
// | Hours   | 60×60×24   (1 day)    | 86,400  |
// | Days    | 60×60×24×7 (1 week)   | 604,800 |
export const REFRESH_TOKEN_TIME_INTERVAL = 60 * 10 // 10 minutes (in seconds)
export const REFRESH_TOKEN_RENEW_CHECKPOINT = 60 * 60 * 6 // 6 hours (in seconds)

// Game constants (from the web.config.json file)
export const GAME_CONFIG_PARTS = env.__GAME_CONFIG__[TARGET_DEPLOYMENT].gameParts
export const GAME_CONFIG_DEFAULTS = env.__GAME_CONFIG__[TARGET_DEPLOYMENT].gameDefaults

// Dashboard constants
export const DASHBOARD_TABLE_HISTORY_AMOUNT = GAME_CONFIG_DEFAULTS.dashboardTableHistoryAmount // Number of rows to display in the dashboard table
export const SUCCESS_THRESHOLD_SIMULATION = GAME_CONFIG_DEFAULTS.successThresholdSimulation // success threshold for the success/failure badges of the dashboard table
export const SUCCESS_THRESHOLD_STUDY = GAME_CONFIG_DEFAULTS.successThresholdStudy // success threshold for the success/failure badges of the dashboard table

// Study constants
export const STUDY_DEFAULT_VALUE = GAME_CONFIG_DEFAULTS.studyDefaultValue // Default number of questions for the study
export const STUDY_MIN_QUESTIONS = GAME_CONFIG_DEFAULTS.studyMinQuestions // Minimum allowed number of questions for the study
export const STUDY_MAX_QUESTIONS = GAME_CONFIG_DEFAULTS.studyMaxQuestions // Maximum allowed number of questions for the study

// Comes from the Vite config
export const GAME_PARTS_DEFAULT = Object.values(GAME_CONFIG_PARTS).findIndex(part => part.default) || 0
/**
 * Gets the config key (0 or 1) from a simulation type ("general" or "specific")
 * @param {string} type - The simulation type ("general" or "specific")
 * @returns {number} The corresponding config key (0 or 1)
 */
export const getGamePartKeyFromType = (type) => {
	// Find the key where partType matches the input type
	const key = Object.entries(GAME_CONFIG_PARTS)
		.find(([_, config]) => config.partType === type)?.[0]

	// Return the found key as number, or GAME_PARTS_DEFAULT if not found
	return key !== undefined ? Number(key) : GAME_PARTS_DEFAULT
}

