const notFoundComponent = "<h2>404 - Page not found</h2>"

// matchRoute function handles both exact and pattern matching
// e.g /study/filters and /study/:id
/**
 * Matches the given path to a route configuration.
 *
 * @function matchRoute
 * @param {string} path - The path to match against the routes.
 * @returns {Object} The matched route configuration and parameters.
 */
export function matchRoute(path) {
	// Check exact routes first
	if (routes[path]) return { route: routes[path], params: {} }

	// Split path into segments
	const pathSegments = path.split("/").filter(Boolean)

	// Check each route for pattern match
	for (const [routePath, routeConfig] of Object.entries(routes)) {
		const routeSegments = routePath.split("/").filter(Boolean)

		if (pathSegments.length !== routeSegments.length) continue

		const params = {}
		const isMatch = routeSegments.every((routeSeg, i) => {
			if (routeSeg.startsWith(":")) {
				// Store param value
				params[routeSeg.slice(1)] = pathSegments[i]
				return true
			}
			return routeSeg === pathSegments[i]
		})

		if (isMatch) {
			return { route: routeConfig, params }
		}
	}

	return { route: routes["/404"], params: {} }
}

/**
 * Fetches the content of a component from the server.
 *
 * @function fetchComponent
 * @param {string} src - The source path of the component.
 * @param {string} component - The component file name.
 * @returns {Promise<string>} The fetched component content.
 * @throws {Error} If the component fetch fails.
 */
export async function fetchComponent(src, component) {
	const response = await fetch(src + component)
	if (!response.ok) throw new Error("Failed to fetch component")

	const content = await response.text()
	if (component !== "/" && content.includes("<body>")) {
		// Check if the content is index.html, if so, replace the body content
		throw new Error("Index page found")
	}
	return content
}

/**
 * Checks if navigation is blocked by the current state.
 *
 * @function isBlockedByState
 * @returns {Promise<boolean>} True if navigation is blocked, false otherwise.
 */
export async function isBlockedByState() {
	const isBlocked = getState().navigationBlocked
	if (!isBlocked) return false

	const confirmed = await showConfirmationDialog("Si abandonas la página perderás tu progreso. ¿Deseas salir?", "Abandonar", "Cancelar")
	if (!confirmed) {
		return true
	}

	updateState({ navigationBlocked: false }) // reset flag
	return false
}

/**
 * Cleans the given window url and updates the browser history.
 * To achieve a clean URL, the found URL and query parameters are removed and stored in the state in the form of
 * {
 * 		currentRoute: "/path",
 * 		queryParams: { key: value }
 * }
 * The browser history is then updated with the destination URL to make it feel like a navigation flow.
 *
 * @function cleanCurrentWindowURL
 * @param {string} dstPath - The destination path to update the browser history.
 * @returns {void}
 */
export function cleanCurrentWindowURL(dstPath) {
	const url = new URL(window.location.href)
	const queryParams = {}
	url.searchParams.forEach((value, key) => {
		queryParams[key] = value
	})

	updateState({
		currentRoute: dstPath,
		queryParams:  queryParams
	})

	window.history.pushState(null, "", dstPath)
}

/**
 * Loads and renders a specific component by its path.
 *
 * @function loadComponent
 * @param {string} fullPath - The route path identifying which component to load.
 * @returns {Promise<void>} Resolves when the component has been loaded.
 * Manages dynamic imports or AJAX requests before updating the page.
 */
export async function loadComponent(dstPath) {
	// const current = getCurrentPath()
	// if (current.path === dstPath) {
	// 	console.debug("Component already loaded:", dstPath)
	// }

	if (!getState().isInitialized) {
		console.debug("App not initialized, deferring load for:", dstPath)
		await new Promise(resolve => setTimeout(resolve, 0))
		return loadComponent(dstPath)
	}

	if (document.readyState !== "complete") {
		await new Promise(resolve => {
			window.addEventListener("load", resolve, { once: true })
		})
	}

	const isBlocked = await isBlockedByState()
	if (isBlocked) return

	const mainContent = document.querySelector("#main-content")
	if (!mainContent) {
		console.warn("Main content element not found, deferring load")
		// 3. Queue the load for next tick after DOM is ready
		setTimeout(() => loadComponent(dstPath), 0)
		return
	}

	try {
		cleanCurrentWindowURL(dstPath)

		// Now parse the destination path, pointed by the app to get the route
		const matchedRoute = matchRoute(dstPath)
		let { route } = matchedRoute
		const { params } = matchedRoute // params are the matched values from the URL, like /result/:id

		if (dstPath !== "/auth") {
			if (!getState().isAuthenticated || route.requiresAuth && session.isStateTokenExpired()) {
				route = routes["/auth"]
			}
		}

		if (route.component) { // Load the component if a reference is found
			updateState({ componentLoading: true })
			mainContent.innerHTML = await fetchComponent(componentsSource, route.component)
		}

		if (route.initialize && typeof route.initialize === "function") {
			route.component ? route.initialize(params) : mainContent.innerHTML = route.initialize(params)

			updateState({ queryParams: "" }) // Reset query params after loading
			window.scrollTo({
				top:      0,
				behavior: "smooth"
			})
		}
	} catch (error) {
		console.error("Error loading component:", error)
		mainContent.innerHTML = notFoundComponent
	} finally {
		updateState({ componentLoading: false })
	}
}

/**
 * Gets the current path and query parameters from the state.
 *
 * @function getCurrentPath
 * @returns {Object} The current path and query parameters.
 */
export function getCurrentPath() {
	return {
		path:  getState().currentRoute,
		query: new URLSearchParams(getState().queryParams || "")
	}
}

/**
 * Builds a full path with query parameters.
 *
 * @function buildPath
 * @param {string} path - The base path.
 * @param {Object} params - The query parameters.
 * @returns {string} The full path with query parameters.
 */
export function buildPath(path, params) {
	const query = new URLSearchParams(params).toString()
	return query ? `${path}?${query}` : path
}

