function handleVersionEndpoint() {
	const versionInfo = {
		debug:       DEBUG,
		version:     WEB_VERSION,
		environment: ENVIRONMENT,
		build:       {
			clientUrl:    CLIENT_URL,
			serverUrl:    SERVER_URL,
			authRequired: AUTH_REQUIRED,
			timestamp:    BUILD_TIMESTAMP,
			globalEnv:    GLOBALENV
		},
		// app: {
		// 	simulationTimeGeneral:  SIMULATION_DEFAULT_TIME_GENERAL,
		// 	simulationTimeSpecific: SIMULATION_DEFAULT_TIME_SPECIFIC
		// }
	}

	// Convert nested object to flat array for table
	const rows = [
		["Version", versionInfo.version],
		["Build Timestamp", versionInfo.build.timestamp],
		["Debug mode", versionInfo.debug],
		["Environment", versionInfo.environment],
		["Client URL", versionInfo.build.clientUrl],
		["Server URL", versionInfo.build.serverUrl],
		["Auth Required", versionInfo.build.authRequired.toString()],
		["Simulation Time (General)", versionInfo.app.simulationTimeGeneral],
		["Simulation Time (Specific)", versionInfo.app.simulationTimeSpecific],

		// Uncomment to display all the environment variables
		// ...Object.entries(versionInfo.build.globalEnv).map(([key, value]) =>
		// 	[key, typeof value === "object" ? JSON.stringify(value) : value]
		// )
	]

	const wrapper = document.createElement("div")
	wrapper.className = "p-6 max-w-2xl mx-auto"

	const title = document.createElement("h2")
	title.className = "text-2xl font-bold mb-4 dark:text-white"
	title.textContent = "Version Information"

	wrapper.appendChild(title)
	wrapper.appendChild(generateTable("firstColumn", "left", rows))

	return wrapper.outerHTML
}

// Listen for custom redirect events from 404.html
window.addEventListener("router-redirect", async (event) => {
	const { path, queryParams } = event.detail
	await loadComponent(path + queryParams) // Forward the full URL (path + query)
})
