import { fetchAPI } from "../api.js"
import {
	DASHBOARD_TABLE_HISTORY_AMOUNT,
	GAME_CONFIG_PARTS,
	GAME_CONFIG_DEFAULTS,
	SUCCESS_THRESHOLD_STUDY,
	getGamePartKeyFromType
} from "../environment.js"
import { showModalX } from "../modals.js"
import { loadComponent } from "../router.js"
import { updateState } from "../states.js"
import { translations, userLanguage } from "../translations.js"
import { Charts } from "./charts.js"
import { generateSubmissionsTable } from "./components.js"
import { StatsCalculations } from "./stats.js" // Update import path

import booksSvg from "../img/books.svg"
import trophyStarSvg from "../img/trophy-star.svg"
import verifiedSvg from "../img/verified.svg"

const MAX_SUBMISSIONS = 200 // Maximum number of submissions to fetch

// Calculate months back based on current month, starting from January 2025
const currentDate = new Date()
const startDate = new Date(2025, 0) // January 2025
const MONTHS_BACK = Math.min(
	4, // Maximum months to show
	(currentDate.getMonth() - startDate.getMonth()) +
    (12 * (currentDate.getFullYear() - startDate.getFullYear())) + 1
)
const DAYS_BACK = Math.min(
	30, // Maximum days to show
	(currentDate.getDate() - startDate.getDate()) +
	(30 * (currentDate.getMonth() - startDate.getMonth())) + 1
)

export class DataService{
	constructor(fetchAPI) {
		this.fetchAPI = fetchAPI
	}

	async getDailyUserStats(days = 30) {
		const { response } = await this.fetchAPI("STATS.USER", "GET", { days })
		return response?.data?.stats || []
	}

	async getDailyLessonStats(months = MONTHS_BACK) {
		const { response } = await this.fetchAPI("STATS.CHART", "GET", { months })
		return response?.data?.stats || []
	}

	async getSubmissions(amount, startDate, endDate) {
		const params = {
			amount: amount,
		}
		// Add filters if provided
		if (startDate) params.startDate = startDate
		if (endDate) params.endDate = endDate

		const { response } = await this.fetchAPI("QUESTIONS.SUBMISSIONS", "GET", params)
		return response?.data?.submissions || []
	}

	async retrieveUserDataFromDB() {
		const { response, error } = await this.fetchAPI("USERS.SELF")
		if (error || !response) {
			showModalX("ERROR DE CONEXIÓN", "El servidor no responde. Inténtalo de nuevo más tarde o si el problema persiste, contacta con soporte.", error.message)
			return
		}
		return response?.data?.user || {}
	}

	async getTotalQuestionCount() {
		const { response, error } = await this.fetchAPI("QUESTIONS.COUNT", "GET")
		if (error || !response) {
			showModalX("ERROR DE CONEXIÓN", "El servidor no responde. Inténtalo de nuevo más tarde o si el problema persiste, contacta con soporte.", error.message)
			return
		}
		return response?.data?.totalQuestions || 0
	}
}

class Home{
	constructor(dataService, chartsService, calculations) {
		this.dataService = dataService
		this.chartsService = chartsService
		this.calculations = calculations
		this.lessonTypes = ["gral.", "esp."]
	}

	async initialize() {
		// Immediately render skeleton UI
		this.renderLoadingState()

		// const authState = getState()
		// if (!authState.isAuthenticated) {
		// 	loadComponent("/auth")
		// 	return // Early return prevents unnecessary DB calls
		// }

		const data = await this.loadData(this.dataService)
		if (!data) {
			console.error("No data received from loadData")
			return
		}
		const { userActivityStats, submissionsHistory, totalQuestionCount, lessonStats } = data

		const normalizedStatsResponse = this.normalizeStatsResponse(lessonStats)
		// extract data from the normalizedStatsResponse to send as chartData
		const chartData = normalizedStatsResponse.map(lesson => lesson.data)
		const chartLegend = normalizedStatsResponse.map(lesson => lesson.alias)
		const chartLabels = this.generateMonthLabels(MONTHS_BACK)

		// Add months here based on the current month
		this.chartsService.initializeLineChart("chart-container", chartLegend, chartLabels, chartData, false, false)

		const gaugeScore = this.calculations.calculateGaugeScore(
			userActivityStats,
			submissionsHistory,
			totalQuestionCount
		)
		this.chartsService.initializeGaugeChart("gauge-chart-container", gaugeScore.toFixed(2), false)

		// Add resize event listener
		// window.addEventListener("resize", () => {
		// 	this.resizeCharts()
		// })
	}

	// Generate month labels like ["Ene", "Feb", ...]
	months = Array.from({ length: 6 }, (_, i) => {
		const date = new Date()
		date.setMonth(date.getMonth() - 5 + i)
		return date.toLocaleString("es-ES", { month: "short" })
	})

	generateMonthLabels(monthsBack = 6) {
		return Array.from({ length: monthsBack }, (_, i) => {
			const date = new Date()
			date.setMonth(date.getMonth() - (monthsBack - 1) + i)
			return date.toLocaleString("es-ES", { month: "short" })
		})
	}

	renderLoadingState() {
		// Show loading states for each section
		this.updateGreeting("", "Cargando...")
		this.renderCardSkeletons()
		this.renderTableSkeleton()

		// FIXME: Enable the dropdown when the data is available
		const preparePeriodsData = null
		this.populatePeriodSelect(this.preparePeriods(preparePeriodsData))
		const dropdownContainer = document.querySelector("#dropdown-container")
		if (!preparePeriodsData && dropdownContainer) {
			dropdownContainer.remove()
		}
	}

	renderCardSkeletons() {
		const cards = Array(4).fill({
			title:       "Cargando...",
			value:       "---",
			description: "Cargando datos...",
			from:        "",
			changeColor: "bg-gray-200 dark:bg-gray-700"
		})
		this.createDashboardCards(cards)
	}

	renderTableSkeleton() {
		const tableContainer = document.querySelector("#submissions-table")
		if (!tableContainer) return
		tableContainer.innerHTML = `
            <div class="animate-pulse">
                <div class="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4 mb-4"></div>
                <div class="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2 mb-4"></div>
                <div class="h-4 bg-gray-200 dark:bg-gray-700 rounded w-5/6"></div>
            </div>
        `
	}

	async loadData(dataService) {
		// Calculate date range (e.g., last 30 days)
		const endDate = new Date()
		const startDate = new Date()
		startDate.setDate(startDate.getDate() - 30) // Last 30 days
		startDate.setHours(0, 0, 0, 0) // Ensure start time is at the beginning of the day

		// Fetch all data in parallel
		const [
			userData, // User profile and preferences
			submissionsHistory, // Previous submissions/attempts
			lessonStats, // Statistics grouped by lesson
			userActivityStats, // User activity metrics
			totalQuestionCount, // Total question count
		] = await Promise.all([
			dataService.retrieveUserDataFromDB(),
			dataService.getSubmissions(MAX_SUBMISSIONS, startDate, endDate),
			dataService.getDailyLessonStats(),
			dataService.getDailyUserStats(),
			dataService.getTotalQuestionCount()
		])

		if (!userData) {
			updateState({ isAuthenticated: false, user: {} })
			loadComponent("/auth")
			return
		}

		const userDisputes = userData.disputes || {}
		updateState({disputes: userDisputes, submissions: submissionsHistory }) // FIXME: Is this messed up? Should it be handled homogeneous with the rest of the data?

		// Update UI as data becomes available
		this.updateGreeting(userData.name, "Hola")
		// const improvementRate = this.calculateImprovement(userActivityStats)
		const streak = this.calculations.calculateStreak(userActivityStats)
		const successRatio = this.calculations.calculateSuccessRatio(userActivityStats)

		this.createDashboardCards(this.prepareDashboardCards(userActivityStats, streak, successRatio, submissionsHistory))
		const limittedSubmissionsHistory = submissionsHistory.slice(0, DASHBOARD_TABLE_HISTORY_AMOUNT)
		this.createDashboardTable(this.prepareDashBoardTable(limittedSubmissionsHistory))

		return {
			userActivityStats,
			submissionsHistory,
			totalQuestionCount,
			lessonStats
		}
	}

	getSimulationTooltip = (part, correctQuestionsAnswerNumber, totalAnswersNumber) => {
		const partKey = getGamePartKeyFromType(part)
		const config = GAME_CONFIG_PARTS[partKey]
		if (!config) return "📊 Puntuación del simulacro"

		const additionalQuestions = config.defaultQuestions - config.validQuestions
		// Helper function to format decimal numbers
		const formatDecimal = (num) => {
			const rounded = Math.round(num * 1000) // Multiply by 1000 to handle 3 decimal places
			if (rounded % 1000 === 0) return rounded / 1000 // If perfectly divisible by 1000, return integer
			return (rounded / 1000).toFixed(3) // Otherwise return 3 decimal places
		}
		const percent = formatDecimal((correctQuestionsAnswerNumber / totalAnswersNumber) * 100)

		return `
📋 Parte ${config.label}
(${config.validQuestions}${additionalQuestions > 0 ? ` (+${additionalQuestions})` : ""} preguntas)
✅ Acierto: +${formatDecimal(config.pointsPerCorrect)} pts
❌ Error: -${formatDecimal(config.pointsPerIncorrect)} pts
📊 (${percent}% acierto)
`
	}

	getStudyTooltip = (correctAnswers, blankAnswers, total) => {
		const percent = Number(((correctAnswers / total) * 100).toFixed(1))
		return `📝 Modo Estudio
✅ ${correctAnswers} correcta${correctAnswers === 1 ? "" : "s"}
❌ ${total - correctAnswers - blankAnswers} incorrecta${total - correctAnswers - blankAnswers === 1 ? "" : "s"}
📊 ${percent}% acierto
Aprobado desde: ${SUCCESS_THRESHOLD_STUDY * 100}%
`
	}

	getPartText = (answers) => {
		if (!answers?.length) return ""

		const part = answers[0]?.extra?.parts
		switch (part) {
		case 1: return ": Fase General"
		case 2: return ": Fase Específica"
		default: return ""
		}
	}

	normalizeStatsResponse(statsResponse) {
		const monthsFromResponse = [...new Set(statsResponse.map(s => s.month))].sort()

		// Group data by lesson_number and type
		const normalizedStats = statsResponse.reduce((acc, { lesson_id, lesson_name, lesson_type, lesson_number, month, passed }) => {
			// Skip lesson_number 0 (Undefined)
			if (lesson_number === 0) return acc

			// Create unique key for lesson
			const key = lesson_id

			if (!acc[key]) {
				acc[key] = {
					name:   key,
					type:   lesson_type,
					number: lesson_number,
					data:   new Array(monthsFromResponse.length).fill(0),
					alias:  `${lesson_name} (${this.lessonTypes[lesson_type]})`
				}
			}

			// Find index for current month and update value
			const monthIndex = monthsFromResponse.indexOf(month)
			if (monthIndex !== -1) {
				acc[key].data[monthIndex] += passed
			}

			return acc
		}, {})

		// Convert to an array of objects to ensure sorting
		const sortedStatsArray = Object.entries(normalizedStats)
			.map(([key, value]) => ({ key, ...value }))
			.sort((a, b) => {
				// Sort by type first (0 before 1)
				if (a.type !== b.type) {
					return a.type - b.type
				}
				// Then sort by lesson number
				return a.number - b.number
			})

		return sortedStatsArray
		// return {
		// 	chartData:   sortedStatsArray,
		// 	chartLegend: sortedStatsArray.map(lesson => lesson.alias)
		// }
	}

	/**
	 * Prepares submission data for dashboard table display
	 * @typedef {Object} Submission
	 * @property {string} id - Submission identifier
	 * @property {string} submissionType - Type of submission (simulation/study)
	 * @property {string} submissionMode - Mode of submission (general/specific)
	 * @property {Array} questionsAnswers - Array of answered questions
	 * @property {string} createdAt - Submission creation timestamp
	 *
	 * @param {Array<Submission>} submissions - Array of submission objects
	 * @returns {Array<Object>} Formatted table rows for display
	 */
	prepareDashBoardTable(submissions) {
		try {
			return submissions.map(this.formatSubmissionForTable.bind(this))
		} catch (err) {
			console.error("Unexpected error in prepareDashBoardTable:", err)
			return []
		}
	}

	/**
	 * Formats a single submission for table display
	 * @param {Submission} submission - Submission object to format
	 * @returns {Object} Formatted table row
	 */
	formatSubmissionForTable(submission) {
		// Get valid questions and counts
		const { validQuestions, totalValidCount, totalCount } = this.getValidQuestions(submission)
		const correctAnswers = this.countCorrectAnswers(validQuestions)
		const blankAnswers = validQuestions.filter(q => q.selectedAnswer === null).length
		const isApproved = this.calculations.isApproved(submission)

		return {
			id:            submission.id,
			date:          this.formatSubmissionDate(submission.createdAt),
			type:          this.getSubmissionTypeText(submission),
			score:         `${correctAnswers}/${totalValidCount}`,
			isApproved:    isApproved,
			status:        this.getSubmissionStatus(submission, isApproved),
			statusTooltip: this.getStatusTooltip(submission, correctAnswers, blankAnswers, totalCount),
			link:          `/results/${submission.id}`
		}
	}

	/**
	 * Gets valid questions based on submission configuration
	 * @param {Object} submission - Submission object
	 * @param {string} submission.submissionType - Type of submission ('simulation' or 'study')
	 * @param {string} submission.submissionMode - Mode of submission (for simulations)
	 * @param {Array} submission.questionsAnswers - Array of question answers
	 * @returns {Object} Object containing valid questions and counts
	 * @property {Array} validQuestions - Array of valid questions to consider
	 * @property {number} totalValidCount - Number of valid questions
	 * @property {number} totalCount - Total number of questions in submission
	 * @throws {Error} If submission is invalid or missing required properties
	 */
	getValidQuestions(submission) {
		// Input validation
		if (!submission?.submissionType || !Array.isArray(submission.questionsAnswers)) {
			throw new Error("Invalid submission format")
		}

		const totalCount = submission.questionsAnswers.length

		// Handle different submission types
		switch (submission.submissionType) {
		case "simulation": {
			const config = GAME_CONFIG_DEFAULTS[getGamePartKeyFromType(submission.submissionMode)]
			const validCount = config?.validQuestions ?? totalCount

			return {
				validQuestions:  submission.questionsAnswers.slice(0, validCount),
				totalValidCount: validCount,
				totalCount
			}
		}

		case "study": {
			return {
				validQuestions:  submission.questionsAnswers,
				totalValidCount: totalCount,
				totalCount
			}
		}

		default:
			throw new Error(`Unknown submission type: ${submission.submissionType}`)
		}
	}

	// Counts correct answers in valid questions
	countCorrectAnswers(validQuestions) {
		return validQuestions.filter(q => q.selectedAnswer === q.accepted).length
	}

	// Gets submission status text
	getSubmissionStatus(submission, isApproved) {
		return submission.submissionType === "simulation"
			? this.calculations.calculateSubmissionScore(submission)
			: isApproved ? translations[userLanguage]["badgePass"] : translations[userLanguage]["badgeFail"]
	}

	// Gets status tooltip
	getStatusTooltip(submission, correctAnswers, blankAnswers, total) {
		return submission.submissionType === "simulation"
			? this.getSimulationTooltip(submission.submissionMode, correctAnswers, total)
			: this.getStudyTooltip(correctAnswers, blankAnswers, total)
	}

	// Gets formatted submission type text
	getSubmissionTypeText(submission) {
		let text = submission.submissionType === "simulation" ? "Simulacro" : "Estudio"
		if (submission.submissionMode) {
			text += ` (${translations[userLanguage][submission.submissionMode]})`
		}
		return text
	}

	// Formats submission date
	formatSubmissionDate(dateString) {
		return new Date(dateString).toLocaleString("es-ES", {
			year:   "numeric",
			month:  "short",
			day:    "numeric",
			hour:   "2-digit",
			minute: "2-digit",
			hour12: false
		})
	}

	createDashboardTable(submissions) {
		// Render the table
		const tableContainer = document.querySelector("#submissions-table")
		if (!tableContainer) return
		if (submissions.length === 0) {
			tableContainer.innerHTML = "<p class='mt-3 text-sm/6 sm:text-xs/6 text-zinc-500'>Aún no hay resultados recientes</p>"
			return
		}
		if (tableContainer.childElementCount > 0) {
			tableContainer.innerHTML = "" // Clear existing content
		}
		const tableElement = generateSubmissionsTable(submissions)
		tableContainer.appendChild(tableElement)
	}

	updateGreeting(name, greeting) {
		const greetingTitle = document.querySelector("#greetings-title")
		if (greetingTitle) {
			greetingTitle.textContent = `${greeting}, ${name}`
		}
	}

	preparePeriods(stats) {
		// FIXME: HARDCODED. Add more periods as needed
		const periods = [{ value: "current_month", label: "Mes actual", hxGet: "", hxTarget: "", hxSwap: "" }]
		return periods
	}

	populatePeriodSelect(periodOptions) {
		const selectElement = document.querySelector("#period-select")
		selectElement.innerHTML = "" // Clear existing options

		periodOptions.forEach(option => {
			const optElement = document.createElement("option")
			optElement.value = option.value
			optElement.textContent = option.label

			// Add HTMX attributes
			optElement.setAttribute("hx-get", option.hxGet)
			optElement.setAttribute("hx-target", option.hxTarget)
			optElement.setAttribute("hx-swap", option.hxSwap)

			selectElement.appendChild(optElement)
		})
	}

	formatImprovement(value) {
		if (value === null) return "--"
		return `${value > 0 ? "+" : ""}${value.toFixed(1)}%`
	}

	getStreakDescription(streak) {
		if (streak === 0) return "¡Empieza hoy tu racha de estudio!"
		if (streak < 5) return "Cada día cuenta para fortalecer tu conocimiento."
		if (streak < 10) return "¡Increíble constancia! Mantén el ritmo."
		if (streak < 15) return "¡Excelente dedicación! Tu esfuerzo se nota."
		if (streak < 20) return "¡Impresionante compromiso! Eres una inspiración."
		return "¡Legendario! Tu dedicación es extraordinaria."
	}

	getDailyImprovementDescription(interval) {
		if (!interval.hasData) {
			return "Sin datos suficientes. ¿A qué esperas para empezar?"
		}

		switch (true) {
		case interval.todayRate === 0:
			return "Sin actividad diaria. ¡Es hora de retomar el estudio!"
		case interval.todayRate > 90:
			return "¡Día excepcional! Has logrado un gran avance hoy."
		case interval.todayRate > 75:
			return "¡Excelente rendimiento! Tu esfuerzo de hoy ha sido sobresaliente."
		case interval.todayRate > 50:
			return "¡Buen trabajo! Hoy has dado un paso importante en tu aprendizaje."
		case interval.todayRate > 25:
			return "¡Sigues avanzando! Cada esfuerzo cuenta para mejorar."
		case interval.todayRate > 10:
			return "¡Bien hecho! Aunque sea un pequeño avance, todo suma."
		case interval.todayRate < 0:
			return "No te preocupes por los altibajos. Mañana es una nueva oportunidad."
		}
	}

	getLongTermImprovementDescription(interval, improvement) {
		if (!interval.hasData) {
			return "Sin datos suficientes. ¿A qué esperas para empezar?"
		}

		switch (true) {
		case improvement > 90:
			return "¡Increíble semana! Tu constancia está marcando la diferencia."
		case improvement > 75:
			return "¡Vas por un camino excelente! Mantente firme en este ritmo."
		case improvement > 50:
			return "¡Gran progreso! Tu esfuerzo sostenido está dando frutos."
		case improvement > 25:
			return "Los resultados están llegando. Sigue con este ritmo y verás más avances."
		case improvement > 10:
			return "¡Bien hecho! Tu avance constante te llevará lejos."
		case improvement > 0:
			return "Cada pequeño avance cuenta. ¡Sigue adelante!"
		case improvement === 0:
			return "Tu progreso está a punto de despegar. ¡Sigue así!"
		default:
			return "Los altibajos son normales en el proceso. Lo importante es mantener el enfoque a largo plazo."
		}
	}

	getApprovedDescription(numberApprovedTests) {
		if (numberApprovedTests === 0) return "Todo gran camino comienza con un primer paso. ¿Listo para empezar?"
		if (numberApprovedTests < 10) return "Cada desafío superado te acerca más a tu meta. ¡Sigue así!"
		if (numberApprovedTests < 30) return "Tu progreso es visible. Se nota el esfuerzo que estás poniendo."
		if (numberApprovedTests < 65) return "Estás construyendo un historial impresionante. ¡Sigue acumulando victorias!"
		if (numberApprovedTests < 90) return "¡Estás en otro nivel! Tu esfuerzo constante te está llevando lejos."
		return "¡Inspirador! Has alcanzado un dominio excepcional. ¿Cuál será tu próximo reto?"
	}

	prepareDashboardCards(userDailyStats, streak, successRatio, submissionsHistory) {
		const interval = this.calculations.determineBestInterval(userDailyStats)
		const improvement = this.calculations.determineImprovement(interval)
		const passed = this.calculations.calculatePassedSubmissions(submissionsHistory)

		const dashboardCards = [
			{
				title:       "Racha de días",
				value:       streak,
				description: this.getStreakDescription(streak),
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				flame:       true,
			},
			{
				title:       `Progreso diario (y con respecto a los últimos ${interval.days} días)`,
				value:       `${interval.todayRate} (${this.formatImprovement(improvement)})`,
				description: `${this.getDailyImprovementDescription(interval)} ${this.getLongTermImprovementDescription(interval, improvement)}`,
				changeColor: improvement > 0
					? "bg-lime-400/20 text-lime-700 dark:bg-lime-400/10 dark:text-lime-300"
					: "bg-red-400/20 text-red-700 dark:bg-red-400/10 dark:text-red-300",
				iconSrc: booksSvg
			},
			{
				title:       "Tasa de éxito",
				value:       `${successRatio ? successRatio + "%" : "--"}`,
				description: successRatio ? "Porcentaje de preguntas correctas sobre las contestadas." : "Sin datos suficientes para calcular.",
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				iconSrc:     trophyStarSvg
			},
			{
				title:  "Pruebas aprobadas",
				values: [
					{
						text:      `Simulacros aprobados: ${passed.simulations > 100 ? "100+" : passed.simulations}`,
						animation: "animate-stat-cycle"
					},
					{
						text:      `Estudios aprobados: ${passed.studies > 100 ? "100+" : passed.studies}`,
						animation: "animate-stat-cycle-delayed"
					}
				],
				description: this.getApprovedDescription(passed.simulations + passed.studies),
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				iconSrc:     verifiedSvg
			}
		]

		return dashboardCards
	}

	createDashboardCards(overviewCards) {
		const overviewCardsContainer = document.querySelector("#overview-cards")
		overviewCardsContainer.innerHTML = ""

		overviewCards.forEach((card) => {
			const cardDiv = document.createElement("div")
			// bg-white dark:bg-zinc-800
			cardDiv.classList.add("border", "rounded-lg", "border-zinc-600", "dark:border-zinc-700")

			const cardHeader = document.createElement("div")
			cardHeader.classList.add("p-6", "flex", "flex-row", "items-center", "justify-between", "space-y-0", "pb-2")

			const cardTitle = document.createElement("div")
			cardTitle.classList.add("tracking-tight", "text-sm", "font-medium", "dark:text-white")
			cardTitle.textContent = card.title

			const cardIcon = document.createElement("span")
			cardIcon.classList.add("dark:text-white")

			if (card.iconSrc) {
				const img = document.createElement("img")
				img.src = card.iconSrc
				img.alt = card.title
				img.classList.add("h-6", "w-6") // "dark:invert"
				cardIcon.appendChild(img)
			} else if (card.icon) {
				cardIcon.innerHTML = card.icon
			}

			if (card.flame) {
				const color1 = "#c33737"
				const color2 = "#f47e60"
				const color3 = "#f8b26a"
				const flameIcon = document.createElement("span")

				flameIcon.innerHTML = `
					<svg xml:space="preserve" viewBox="35 10 10 75" class="w-6 h-6 m-0 block" preserveAspectRatio="xMidYMid">
						<g class="origin-center scale-[0.8] rotate-0">
							<g>
								<g>
									<g class="[transform-box:view-box] [transform-origin:50px_50px] opacity-100 animate-tremble-1 group-hover:duration-[1500ms]">
										<path fill="${color1}" stroke-width="0.95"
											d="M58.5 7.5c-18.3 9.6-35.4 28.2-35.4 49.3 0 5.4.7 10.7 2.1 15.6 7.2 26.8 42.5 26.8 49.7 0 1.3-5 2-10.2 2.1-15.6.2-20.2-20.1-32-18.5-49.3z">
										</path>
									</g>
								</g>
								<g>
									<g class="[transform-box:view-box] [transform-origin:50px_50px] opacity-100 animate-tremble-2 delay-[500ms] group-hover:duration-[1500ms]">
										<path fill="${color2}" stroke-width="0.95"
											d="M50 32.7c-11.3 6-18.9 17.5-18.9 30.7 0 3.4.5 6.7 1.4 9.8 5.1 16.8 29.8 16.8 34.9 0 .9-3.1 1.4-6.4 1.4-9.8.1-13.2-7.5-24.7-18.8-30.7z">
										</path>
									</g>
								</g>
								<g>
									<g class="[transform-box:view-box] [transform-origin:50px_50px] opacity-100 animate-tremble-3 delay-[1000ms] group-hover:duration-[1500ms]">
										<path fill="${color3}" stroke-width="0.95"
											d="M50 47.5C43.2 51.2 38.6 58.1 38.6 66c0 2 .3 4 .9 5.9 3.1 10.1 17.9 10.1 21 0 .6-1.9.9-3.8.9-5.9 0-7.9-4.6-14.8-11.4-18.5z">
										</path>
									</g>
								</g>
							</g>
						</g>
					</svg>
				`
				cardIcon.appendChild(flameIcon)
			}

			cardHeader.appendChild(cardTitle)
			cardHeader.appendChild(cardIcon)
			cardDiv.appendChild(cardHeader)

			const cardBody = document.createElement("div")
			cardBody.classList.add("p-6", "pt-0")

			if (card.values) {
				const cardValue = document.createElement("div")

				// FIXME: Make this responsive instead of fixed
				cardValue.classList.add("relative", "h-8") // Fixed height container

				card.values.forEach((value, index) => {
					const statDiv = document.createElement("div")
					const classes = [
						value.animation,
						"absolute",
						"inset-0",
						"text-2xl",
						"font-bold",
						"dark:text-white",
						// Add initial opacity state
						index === 0 ? "opacity-100" : "opacity-0"
					]
					statDiv.classList.add(...classes)
					statDiv.textContent = value.text
					cardValue.appendChild(statDiv)

					// FIXME: Enlarge margins when the text is too long
					if (value.text.length > 22) {
						cardValue.classList.remove("h-8")
						cardValue.classList.add("h-14")
					}

				})
				cardBody.appendChild(cardValue)

				const cardDescription = document.createElement("p")
				cardDescription.classList.add("text-xs", "text-muted-foreground", "dark:text-white", "xl:mt-10")
				cardDescription.textContent = card.description
				cardBody.appendChild(cardDescription)
			} else {
				const cardValue = document.createElement("div")
				cardValue.classList.add("text-2xl", "font-bold", "dark:text-white")
				cardValue.textContent = card.value

				const cardDescription = document.createElement("p")
				cardDescription.classList.add("text-xs", "text-muted-foreground", "dark:text-white")
				cardDescription.textContent = card.description

				cardBody.appendChild(cardValue)
				cardBody.appendChild(cardDescription)
			}

			cardDiv.appendChild(cardBody)

			overviewCardsContainer.appendChild(cardDiv)
		})
	}
}

export const homeComponent = new Home(
	new DataService(fetchAPI),
	new Charts(),
	StatsCalculations
)
export const initializeHome = () => homeComponent.initialize()
