export function generateSearchBox(searchPlaceholder = "Search...", options = {}, width = "w-full", height = "h-48", name = "options") {
	// Create a wrapper div for the search bar and scrollable content
	const wrapper = document.createElement("div")

	// Create the search input
	const searchInput = document.createElement("input")
	searchInput.type = "text"
	searchInput.placeholder = searchPlaceholder
	searchInput.className = `
        w-full mb-2 px-3 py-2 border border-zinc-300 dark:border-zinc-700
        rounded-md text-sm text-zinc-900 dark:text-white
        bg-white dark:bg-zinc-800 focus:outline-none
        focus:ring-2 focus:ring-zinc-500
    `

	// Append the search input to the wrapper
	wrapper.appendChild(searchInput)

	// Create the scrollable container for checkboxes
	const scrollContainer = document.createElement("div")
	scrollContainer.className = `
        overflow-y-auto ${width} ${height}
        border border-zinc-300 dark:border-zinc-700
        rounded-md p-2 bg-white dark:bg-zinc-900
    `

	// Generate and append checkboxes to the scroll container
	Object.entries(options).forEach(([key, value]) => {
		const checkboxLabel = document.createElement("label")
		checkboxLabel.className = "flex items-center space-x-3 cursor-pointer mb-2"

		const checkbox = document.createElement("input")
		checkbox.type = "checkbox"
		checkbox.name = name
		checkbox.value = key // Use the key as the value
		checkbox.className = "sr-only"

		// Custom checkbox styling with SVG for checked state
		const checkIndicator = document.createElement("span")
		checkIndicator.className = "flex h-5 w-5 items-center justify-center border-2 border-zinc-400 rounded-md dark:border-zinc-600 transition-colors"

		const checkMark = document.createElementNS("http://www.w3.org/2000/svg", "svg")
		checkMark.setAttribute("xmlns", "http://www.w3.org/2000/svg")
		checkMark.setAttribute("class", "h-3 w-3 text-white")
		checkMark.setAttribute("fill", "none")
		checkMark.setAttribute("viewBox", "0 0 24 24")
		checkMark.setAttribute("stroke", "currentColor")
		checkMark.setAttribute("stroke-width", "2")

		const path = document.createElementNS("http://www.w3.org/2000/svg", "path")
		path.setAttribute("stroke-linecap", "round")
		path.setAttribute("stroke-linejoin", "round")
		path.setAttribute("d", "M5 13l4 4L19 7")
		checkMark.appendChild(path)

		// Append check mark to indicator, but initially hidden
		checkMark.style.display = "none"
		checkIndicator.appendChild(checkMark)

		// Show or hide check mark based on checkbox state
		checkbox.addEventListener("change", () => {
			if (checkbox.checked) {
				checkIndicator.classList.add("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
				checkMark.style.display = "block"
			} else {
				checkIndicator.classList.remove("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
				checkMark.style.display = "none"
			}
		})

		// Option label text
		const optionLabel = document.createElement("span")
		optionLabel.className = "text-sm text-zinc-900 dark:text-zinc-100"
		optionLabel.textContent = value // Use the value for display

		// Assemble each checkbox label
		checkboxLabel.appendChild(checkbox)
		checkboxLabel.appendChild(checkIndicator)
		checkboxLabel.appendChild(optionLabel)

		// Add to the scroll container
		scrollContainer.appendChild(checkboxLabel)
	})

	// Append the scroll container to the main wrapper
	wrapper.appendChild(scrollContainer)

	searchInput.addEventListener("input", () => {
		const filter = normalizeText(searchInput.value)

		Array.from(scrollContainer.children).forEach(child => {
			const label = child.querySelector("span:last-child")
			if (!label) return
			// Store normalized version if not already stored
			if (!label.dataset.normalized) {
				label.dataset.normalized = normalizeText(label.textContent)
			}

			child.style.display = label.dataset.normalized.includes(filter) ? "" : "none"
		})
	})

	// Return both the wrapper and the scrollable container
	return wrapper
}

export function showConfirmationDialog(message, confirmText = "Sí", cancelText = "No") {
	return new Promise((resolve) => {
		const dialog = generateDialog({
			children: [
				(() => {
					const messageElement = document.createElement("p")
					messageElement.className = "text-gray-700 dark:text-gray-300 mb-4"
					messageElement.textContent = message
					return messageElement
				})()
			],
			onConfirm:   () => resolve(true),
			onCancel:    () => resolve(false),
			confirmText: confirmText,
			cancelText:  cancelText
		})

		// Show the dialog
		dialog.showDialog()
	})
}

export function generateCheckboxes(name, label, options) {
	// Create the main wrapper
	const wrapper = document.createElement("div")
	wrapper.className = "space-y-4"

	// Add a label for the entire checkbox group
	const groupLabel = document.createElement("label")
	groupLabel.className = "block text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-2"
	groupLabel.textContent = label
	wrapper.appendChild(groupLabel)

	// Create each checkbox option
	options.forEach(optionText => {
		// Unique ID for each checkbox
		const checkboxId = `${name}-${optionText.replace(/\s+/g, "-").toLowerCase()}`

		// Create label for each checkbox item
		const itemLabel = document.createElement("label")
		itemLabel.className = "flex items-center space-x-3 cursor-pointer"

		// Hidden checkbox input
		const checkbox = document.createElement("input")
		checkbox.type = "checkbox"
		checkbox.name = name
		checkbox.value = optionText
		checkbox.id = checkboxId
		checkbox.className = "sr-only" // Hides the checkbox itself

		// Visual indicator with a check mark
		const checkIndicator = document.createElement("span")
		checkIndicator.className = "flex h-5 w-5 items-center justify-center border-2 border-zinc-400 rounded-md dark:border-zinc-600 transition-colors"

		// SVG check mark, shown when checkbox is checked
		const checkMark = document.createElementNS("http://www.w3.org/2000/svg", "svg")
		checkMark.setAttribute("xmlns", "http://www.w3.org/2000/svg")
		checkMark.setAttribute("class", "h-3 w-3 text-white")
		checkMark.setAttribute("fill", "none")
		checkMark.setAttribute("viewBox", "0 0 24 24")
		checkMark.setAttribute("stroke", "currentColor")
		checkMark.setAttribute("stroke-width", "2")

		const path = document.createElementNS("http://www.w3.org/2000/svg", "path")
		path.setAttribute("stroke-linecap", "round")
		path.setAttribute("stroke-linejoin", "round")
		path.setAttribute("d", "M5 13l4 4L19 7")
		checkMark.appendChild(path)

		// Append check mark to indicator, but initially hidden
		checkMark.style.display = "none"
		checkIndicator.appendChild(checkMark)

		// Show or hide check mark based on checkbox state
		checkbox.addEventListener("change", () => {
			if (checkbox.checked) {
				checkIndicator.classList.add("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
				checkMark.style.display = "block"
			} else {
				checkIndicator.classList.remove("bg-zinc-900", "border-transparent", "dark:bg-zinc-600")
				checkMark.style.display = "none"
			}
		})

		// Label text
		const optionLabel = document.createElement("span")
		optionLabel.className = "text-sm text-zinc-900 dark:text-zinc-100"
		optionLabel.textContent = optionText

		// Assemble elements
		itemLabel.appendChild(checkbox)
		itemLabel.appendChild(checkIndicator)
		itemLabel.appendChild(optionLabel)
		wrapper.appendChild(itemLabel)
	})

	return wrapper
}

export function createNavLink(href, text) {
	// Create the anchor element
	const link = document.createElement("a")
	link.className = "inline-flex items-center box-content gap-2 text-sm/6 text-zinc-500 dark:text-zinc-400"
	link.href = href

	// Create the SVG icon
	link.innerHTML = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" data-slot="icon" class="size-4 fill-zinc-400 dark:fill-zinc-500">
            <path fill-rule="evenodd" d="M9.78 4.22a.75.75 0 0 1 0 1.06L7.06 8l2.72 2.72a.75.75 0 1 1-1.06 1.06L5.47 8.53a.75.75 0 0 1 0-1.06l3.25-3.25a.75.75 0 0 1 1.06 0Z" clip-rule="evenodd"></path>
        </svg>
    `

	// Add the text content
	const linkText = document.createTextNode(text)
	link.appendChild(linkText)

	return link
}

export function generateDialog({ children = [], onConfirm, onCancel, confirmText = "Aceptar", cancelText = "Cancelar" } = {}) {
	const dialogWrapper = document.createElement("div")
	dialogWrapper.className = "fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-gray-800 bg-opacity-50 hidden"
	dialogWrapper.style.display = "none"

	const dialogContainer = document.createElement("div")
	dialogContainer.className = "w-full max-w-lg sm:rounded-2xl rounded-t-3xl bg-white dark:bg-zinc-900 p-6 shadow-lg ring-1 ring-zinc-900/10 sm:mb-auto sm:mt-auto"
	dialogWrapper.appendChild(dialogContainer)

	// Append children
	children.forEach(child => {
		dialogContainer.appendChild(child)
	})

	const buttonContainer = document.createElement("div")
	buttonContainer.className = "mt-6 flex items-center justify-end gap-3"
	dialogContainer.appendChild(buttonContainer)

	const hideDialog = () => {
		dialogWrapper.style.display = "none"
		// Optional: Remove from DOM after hiding
		// document.body.removeChild(dialogWrapper)
	}

	// Cancel Button
	const cancelButton = generateButton("cancel", cancelText, "button", "secondary")
	cancelButton.addEventListener("click", () => {
		if (onCancel) onCancel(dialogContainer)
		hideDialog()
	})
	buttonContainer.appendChild(cancelButton)

	// Confirm Button
	const confirmButton = generateButton("confirm", confirmText, "button", "primary")
	confirmButton.addEventListener("click", async () => {
		if (onConfirm) {
			await onConfirm(dialogContainer)
		}
		hideDialog()
	})
	buttonContainer.appendChild(confirmButton)

	// Overlay click
	dialogWrapper.addEventListener("click", () => {
		if (onCancel) onCancel(dialogContainer)
		hideDialog()
	})

	// Prevent click propagation
	dialogContainer.addEventListener("click", (e) => e.stopPropagation())

	document.body.appendChild(dialogWrapper)

	return {
		showDialog: () => dialogWrapper.style.display = "flex",
		hideDialog,
		dialogContainer
	}
}

export function generateDialogV1({ children = [], onConfirm, onCancel, confirmText = "Aceptar", cancelText = "Cancelar" } = {}) {
	const dialogWrapper = document.createElement("div")
	dialogWrapper.className = "fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-gray-800 bg-opacity-50 hidden"
	dialogWrapper.style.display = "none" // Initially hidden

	// Dialog container
	const dialogContainer = document.createElement("div")
	dialogContainer.className = "w-full max-w-lg sm:rounded-2xl rounded-t-3xl bg-white dark:bg-zinc-900 p-6 shadow-lg ring-1 ring-zinc-900/10 sm:mb-auto sm:mt-auto"
	dialogWrapper.appendChild(dialogContainer)

	// Append custom children to dialog
	children.forEach(child => {
		dialogContainer.appendChild(child)
	})

	// Button Container
	const buttonContainer = document.createElement("div")
	buttonContainer.className = "mt-6 flex items-center justify-end gap-3"
	dialogContainer.appendChild(buttonContainer)

	// Cancel Button
	const cancelButton = generateButton("cancel", cancelText, "button", "secondary")
	cancelButton.addEventListener("click", () => {
		if (onCancel) onCancel()
		dialogWrapper.style.display = "none"
	})
	buttonContainer.appendChild(cancelButton)

	// Confirm Button
	const confirmButton = generateButton("confirm", confirmText, "button", "primary")
	confirmButton.addEventListener("click", () => {
		if (onConfirm) onConfirm()
		dialogWrapper.style.display = "none"
	})
	buttonContainer.appendChild(confirmButton)

	// Overlay click to close
	dialogWrapper.addEventListener("click", () => {
		if (onCancel) onCancel()
		dialogWrapper.style.display = "none"
	})

	// Stop propagation to keep dialog open when clicking inside
	dialogContainer.addEventListener("click", (e) => e.stopPropagation())

	// Append to body or desired container
	document.body.appendChild(dialogWrapper)

	// Show Dialog
	const showDialog = () => {
		dialogWrapper.style.display = "flex"
	}

	// Return the dialog control function
	return { showDialog }
}

export function generateTable(headerPosition, alignment = "center", rows) {
	// Create main wrapper for the table
	const wrapper = document.createElement("div")
	// Apply alignment-specific and common classes together
	if (alignment === "left") {
		wrapper.className = "mx-auto max-w-3xl overflow-hidden"
	} else {
		wrapper.className = "text-center overflow-hidden sm:mx-0 sm:max-w-full"
	}

	// Add common styles
	wrapper.className += " border border-zinc-200 rounded-lg dark:border-white/10 dark:bg-zinc-900 p-3 sm:p-4"

	// Table element
	const table = document.createElement("dl")
	table.className = `
        grid grid-cols-1 text-base/6 grid-cols-[min(50%,theme(spacing.80))_auto] sm:text-sm/6
    `

	// Process each row
	rows.forEach((row, rowIndex) => {
		row.forEach((cellContent, colIndex) => {
			// Determine if this cell should be treated as a header
			const isRowHeader = headerPosition === "firstRow" && rowIndex === 0
			const isColHeader = headerPosition === "firstColumn" && colIndex === 0
			const isBothHeader = headerPosition === "both" && (rowIndex === 0 || colIndex === 0)
			const isHeader = isRowHeader || isColHeader || isBothHeader

			// Create the cell element (either `dt` for headers or `dd` for data cells)
			const cell = document.createElement(isHeader ? "dt" : "dd")

			// Apply text content and styling
			cell.textContent = cellContent
			cell.className = `
                ${isHeader ? "text-zinc-500 dark:text-zinc-400" : "text-zinc-950 dark:text-white"}
                ${rowIndex > 0 || isHeader ? "border-t border-zinc-950/5 dark:border-white/5" : ""}
                ${isHeader ? "first:border-none" : ""}
            `
			// ${isHeader ? "pt-3" : "pb-3 pt-1"}

			cell.className += " py-2 sm:py-3"
			// Append cell to the table
			table.appendChild(cell)
		})
	})

	// Append table to wrapper
	wrapper.appendChild(table)

	return wrapper
}

